6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2013,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 6.40\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T59e,"])self.__next_f.push([1,"“If someone gives up all material prospects and takes complete shelter of the Supreme Personality of Godhead, there is no loss or degradation in any way. On the other hand a nondevotee may fully engage in his occupational duties and yet not gain anything.” For material prospects there are many activities, both scriptural and customary. A transcendentalist is supposed to give up all material activities for the sake of spiritual advancement in life, Kṛṣṇa consciousness. One may argue that by Kṛṣṇa consciousness one may attain the highest perfection if it is completed, but if one does not attain such a perfectional stage, then he loses both materially and spiritually. It is enjoined in the scriptures that one has to suffer the reaction for not executing prescribed duties; therefore one who fails to discharge transcendental activities properly becomes subjected to these reactions. The Bhāgavatam assures the unsuccessful transcendentalist that there need be no worries. Even though he may be subjected to the reaction for not perfectly executing prescribed duties, he is still not a loser, because auspicious Kṛṣṇa consciousness is never forgotten, and one so engaged will continue to be so even if he is lowborn in the next life. On the other hand, one who simply follows strictly the prescribed duties need not necessarily attain auspicious results if he is lacking in Kṛṣṇa consciousness."])self.__next_f.push([1,"26:T5df,"])self.__next_f.push([1,"Those who are following the path of auspiciousness can be divided into three sections, namely (1) the followers of scriptural rules and regulations who are enjoying material prosperity, (2) those who are trying to find ultimate liberation from material existence, and (3) those who are devotees in Kṛṣṇa consciousness. Those who are following the rules and regulations of the scriptures for material happiness may be further divided into two classes: those who are fruitive workers and those who desire no fruit for sense gratification. Those who are after fruitive results for sense gratification may be elevated to a higher standard of life – even to the higher planets – but still, because they are not free from material existence, they are not following the truly auspicious path. The only auspicious activities are those which lead one to liberation. Any activity which is not aimed at ultimate self-realization or liberation from the material bodily concept of life is not at all auspicious. Activity in Kṛṣṇa consciousness is the only auspicious activity, and anyone who voluntarily accepts all bodily discomforts for the sake of making progress on the path of Kṛṣṇa consciousness can be called a perfect transcendentalist under severe austerity. And because the eightfold yoga system is directed toward the ultimate realization of Kṛṣṇa consciousness, such practice is also auspicious, and no one who is trying his best in this matter need fear degradation."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2013,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"40\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 40\",\"advanced_view_url_path\":\"/en/library/bg/6/advanced-view/#bb1781\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/6/40/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/6/40/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/6/40/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/6/40/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/6/40/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/6/40/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/6/40/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/6/40/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/hr/library/bg/6/40/\"},{\"display_name\":\"Magyar (Hungarian)\",\"language_code\":\"hu\",\"enabled\":true,\"url_path\":\"/hu/library/bg/6/40/\"},{\"display_name\":\"日本語 (Japanese)\",\"language_code\":\"ja\",\"enabled\":true,\"url_path\":\"/ja/library/bg/6/40/\"},{\"display_name\":\"한국어 (Korean)\",\"language_code\":\"ko\",\"enabled\":true,\"url_path\":\"/ko/library/bg/6/40/\"},{\"display_name\":\"Lietuvių kalba (Lithuanian)\",\"language_code\":\"lt\",\"enabled\":true,\"url_path\":\"/lt/library/bg/6/40/\"},{\"display_name\":\"Nederlands (Dutch)\",\"language_code\":\"nl\",\"enabled\":true,\"url_path\":\"/nl/library/bg/6/40/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/6/40/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/6/40/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/6/40/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/6/40/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/6/40/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/6/40/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/6/\",\"title\":\"Chapter Six: Dhyāna-yoga\"}],\"url_path\":\"/en/library/bg/6/40/\",\"bb\":1781,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/6/39/\",\"title\":\"TEXT 39\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\